#!/bin/sh
# The vendored OpenD protobuf definitions and the Go generated from them.
#
#   futu-proto.sh check [ROOT]   bind files to the manifest; needs no protoc
#   futu-proto.sh regen          regenerate and rewrite the manifest; needs protoc
#
# check binds every vendored definition and generated file to its manifest
# line, every generated header to the manifest's generator versions, and the
# two go.mod pins of google.golang.org/protobuf to the manifest's runtime
# line. It cannot tell whether the generated code came from these definitions;
# only a regeneration followed by `git diff --exit-code pkg/futu/internal/pb`
# can, which is what the CI job runs. regen refuses unless `protoc --version`
# equals the manifest's, and preserves the hand-kept archive checksum lines.
#
# Trd_UnlockTrade.proto is never vendored: its absence is part of the
# guarantee that no build of the client can unlock a trading account.

set -eu

module=github.com/osauer/canary/v2
pb=pkg/futu/internal/pb

fail() {
	printf 'futu-proto: %s\n' "$1" >&2
	exit 1
}

sha256() {
	if command -v sha256sum >/dev/null 2>&1; then
		sha256sum "$1" | cut -d' ' -f1
	else
		shasum -a 256 "$1" | cut -d' ' -f1
	fi
}

# manifest_value KEY: the rest of the line after KEY in the manifest.
manifest_value() {
	sed -n "s/^$1 //p" "$manifest" | sed -n 1p
}

# go_mod_version FILE: the version FILE pins for the protobuf runtime.
go_mod_version() {
	sed -n 's/^[[:space:]]*google\.golang\.org\/protobuf \(v[^ ]*\).*/\1/p' "$1" | sed -n 1p
}

lower_name() {
	printf '%s' "$1" | tr '[:upper:]' '[:lower:]'
}

check() {
	root=$1
	manifest=$root/$pb/MANIFEST
	[ -f "$manifest" ] || fail "$pb/MANIFEST is missing"
	protoc_header=$(manifest_value protoc-header)
	generator=$(manifest_value protoc-gen-go)
	runtime=$(manifest_value protobuf-runtime)
	[ -n "$(manifest_value protoc-version)" ] || fail 'the manifest names no protoc-version'
	[ -n "$protoc_header" ] || fail 'the manifest names no protoc-header'
	[ -n "$generator" ] || fail 'the manifest names no protoc-gen-go'
	[ -n "$runtime" ] || fail 'the manifest names no protobuf-runtime'
	[ -n "$(manifest_value 'archive [^ ]*')" ] || fail 'the manifest names no protoc archive checksum'

	for gomod in go.mod tools/go.mod; do
		pinned=$(go_mod_version "$root/$gomod")
		[ "$pinned" = "$runtime" ] ||
			fail "$gomod pins google.golang.org/protobuf ${pinned:-nowhere}; the manifest says $runtime"
	done

	[ ! -e "$root/$pb/proto/Trd_UnlockTrade.proto" ] ||
		fail 'Trd_UnlockTrade.proto is vendored; no build of the client may unlock an account'

	expected=$(sed -nE 's/^(proto|go) [0-9a-f]+ //p' "$manifest" | LC_ALL=C sort)
	[ -n "$expected" ] || fail 'the manifest lists no files'
	actual=$(cd "$root/$pb" && find . -type f \( -name '*.proto' -o -name '*.pb.go' \) | sed 's|^\./||' | LC_ALL=C sort)
	if [ "$expected" != "$actual" ]; then
		printf 'futu-proto: the files on disk differ from the manifest:\n' >&2
		printf '%s\n' "$expected" >"$root/.futu-proto-expected.$$"
		printf '%s\n' "$actual" | diff "$root/.futu-proto-expected.$$" - >&2 || true
		rm -f "$root/.futu-proto-expected.$$"
		exit 1
	fi

	while read -r kind sum path; do
		case "$kind" in
		proto | go) ;;
		*) continue ;;
		esac
		got=$(sha256 "$root/$pb/$path")
		[ "$got" = "$sum" ] || fail "$pb/$path does not match its manifest line"
		if [ "$kind" = go ]; then
			grep -Eq "^//[[:space:]]+protoc-gen-go ${generator}\$" "$root/$pb/$path" ||
				fail "$pb/$path was not generated by protoc-gen-go $generator"
			grep -Eq "^//[[:space:]]+protoc[[:space:]]+${protoc_header}\$" "$root/$pb/$path" ||
				fail "$pb/$path was not generated by protoc $protoc_header"
		fi
	done <"$manifest"
	count=$(printf '%s\n' "$expected" | grep -c '\.proto$')
	printf 'futu-proto: OK (%s definitions; protoc-gen-go %s; protoc %s)\n' "$count" "$generator" "$protoc_header"
}

regen() {
	root=$(git rev-parse --show-toplevel)
	cd "$root"
	manifest=$pb/MANIFEST
	[ -f "$manifest" ] || fail "$manifest is missing; its protoc-version and archive lines are hand-kept"
	want=$(manifest_value protoc-version)
	have=$(protoc --version 2>/dev/null) || fail "protoc is not on PATH; the manifest names $want"
	[ "$have" = "$want" ] || fail "protoc reports '$have'; the manifest names '$want'"
	plugin=$(go -C tools tool -n protoc-gen-go) || fail 'tools/go.mod does not pin protoc-gen-go'
	generator=$("$plugin" --version | sed -n 's/^protoc-gen-go //p')

	# One Go package per definition, because each declares its own package and
	# most declare top-level Request, Response, C2S and S2C. The upstream
	# go_package does not resolve, so every import path is mapped here and the
	# vendored files stay byte-identical to upstream.
	mappings=
	files=
	for file in "$pb"/proto/*.proto; do
		name=$(basename "$file")
		stem=${name%.proto}
		mappings="$mappings --go_opt=M$name=$module/$pb/$(lower_name "$stem")"
		files="$files $name"
	done
	find "$pb" -type f -name '*.pb.go' -delete
	find "$pb" -mindepth 1 -type d -empty -delete
	# shellcheck disable=SC2086 # the two lists are space-free by construction
	protoc --proto_path="$pb/proto" --plugin=protoc-gen-go="$plugin" \
		--go_out=. --go_opt=module="$module" $mappings $files

	first=$(find "$pb" -type f -name '*.pb.go' | sort | sed -n 1p)
	[ -n "$first" ] || fail 'protoc generated nothing'
	header=$(sed -n 's/^\/\/[[:space:]]*protoc[[:space:]]\{1,\}\(v[^ ]*\)$/\1/p' "$first" | sed -n 1p)
	[ -n "$header" ] || fail "$first carries no protoc version line"

	tmp=$manifest.tmp.$$
	{
		sed -n '/^#/p' "$manifest"
		printf 'protoc-version %s\n' "$want"
		printf 'protoc-header %s\n' "$header"
		printf 'protoc-gen-go %s\n' "$generator"
		printf 'protobuf-runtime %s\n' "$generator"
		sed -n '/^archive /p' "$manifest"
		for file in "$pb"/proto/*.proto; do
			printf 'proto %s %s\n' "$(sha256 "$file")" "${file#"$pb"/}"
		done
		find "$pb" -type f -name '*.pb.go' | LC_ALL=C sort | while read -r file; do
			printf 'go %s %s\n' "$(sha256 "$file")" "${file#"$pb"/}"
		done
	} >"$tmp"
	mv "$tmp" "$manifest"
	check "$root"
}

case "${1:-}" in
check) check "${2:-$(git rev-parse --show-toplevel)}" ;;
regen) regen ;;
*) fail 'usage: futu-proto.sh check [ROOT] | regen' ;;
esac
